## Code Example
```javascript
// Pseudo-handler: on POST /orders with idempotencyKey
if (!store.has(key)) {
  const order = createOrder(payload);
  publishKafka(order);
  store.set(key, order.id, ttl);
  return { status: 200, body: { orderId: order.id } };
